package com.example.userservice.service;

import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.client.RestClientTest;
import org.springframework.http.MediaType;
import org.springframework.test.web.client.MockRestServiceServer;

import java.util.Map;

import static org.junit.jupiter.api.Assertions.*;
import static org.springframework.test.web.client.match.MockRestRequestMatchers.requestTo;
import static org.springframework.test.web.client.match.MockRestRequestMatchers.method;
import static org.springframework.test.web.client.response.MockRestResponseCreators.withSuccess;
import static org.springframework.http.HttpMethod.GET;
import static org.springframework.http.HttpMethod.POST;
import static org.springframework.http.HttpMethod.DELETE;

@RestClientTest(ExternalApiService.class)
class ExternalApiServiceTest {

    @Autowired
    private ExternalApiService externalApiService;

    @Autowired
    private MockRestServiceServer server;

    @Autowired
    private ObjectMapper objectMapper;

    @Test
    void verifyEmail_Success() throws Exception {
        String email = "test@example.com";
        String responseJson = "{\"valid\": true}";

        server.expect(requestTo("https://api.example.com/verify/email?email=" + email))
                .andExpect(method(GET))
                .andRespond(withSuccess(responseJson, MediaType.APPLICATION_JSON));

        boolean isValid = externalApiService.verifyEmail(email);

        assertTrue(isValid);
    }

    @Test
    void sendNotification_Success() throws Exception {
        String userId = "123";
        String message = "Welcome!";

        server.expect(requestTo("https://api.example.com/notifications"))
                .andExpect(method(POST))
                .andRespond(withSuccess());

        assertDoesNotThrow(() -> externalApiService.sendNotification(userId, message));
    }

    @Test
    void enrichUserProfile_Success() throws Exception {
        String userId = "123";
        String responseJson = "{\"preferences\": \"dark_mode\", \"score\": 100}";

        server.expect(requestTo("https://api.example.com/users/" + userId + "/profile"))
                .andExpect(method(GET))
                .andRespond(withSuccess(responseJson, MediaType.APPLICATION_JSON));

        Map<String, Object> profile = externalApiService.enrichUserProfile(userId);

        assertNotNull(profile);
        assertEquals("dark_mode", profile.get("preferences"));
        assertEquals(100, profile.get("score"));
    }

    @Test
    void requestDataDeletion_Success() {
        String userId = "123";

        server.expect(requestTo("https://api.example.com/users/" + userId + "/data"))
                .andExpect(method(DELETE))
                .andRespond(withSuccess());

        boolean result = externalApiService.requestDataDeletion(userId);

        assertTrue(result);
    }
}
